---level46 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl46_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end		game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		if dialog.show("Level46-1", faceWeixiao) ==1 then break end		sound.play("46-1");		camera.setFollowRoleMode(false)		camera.gotoPosition(416,368)		if dialog.show("Level46-2", faceJingya) ==1 then break end		sound.play("60-1");		if dialog.show("Level46-3", faceWunai) ==1 then break end		sound.play("43-1");		if dialog.show("Level46-4", faceRenzhen) ==1 then break end		sound.play("54-1");		if dialog.show("Level46-5", faceDeyi) ==1 then break end		camera.gotoRole()		if dialog.show("Level46-6", faceManyi) ==1 then break end		camera.setFollowRoleMode(true)				--set story viewed flag        global.setBool("lvl46_b1")		game.restartTiming()		game.setUserInputEnabled(true)		role.setIdleActionEnabled(true)		isPlayingDemo = false		isSkip = false	until trueendif isSkip then	camera.gotoRole()	camera.setFollowRoleMode(true)	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()end